    if (node.type === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === null ? k : `${path}.${k}`
        const child = node.entries.get(k)
        lines.push(`${p} ${child.type}`)
        walk(child, p)
      }
    } else if (node.type === 'array') {
      node.items.forEach((child, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${child.type}`)
        walk(child, p)
      })
    }
  }
  walk(root, null)
  return lines.length ? lines.join('\n') + '\n' : ''
}
"}

