  constructor(reason) {
    super(reason)
    this.reason = reason
    this.line = 0
  }
}

const fail = (reason) => {
  throw new ParseError(reason)
}

const newTable = () => ({ type: 'table', entries: new Map(), made: false })
const BARE = /[A-Za-z0-9_-]/
const INT = /^[+-]?\d+(?:_\d+)*$/
const FLOAT = /^[+-]?\d+(?:_\d+)*(?:\.\d+(?:_\d+)*)?(?:[eE][+-]?\d+(?:_\d+)*)?$/

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  ws() {
    while (this.s[this.i] === ' ' || this.s[this.i] === '\t') this.i++
  }
  atEnd() {
    this.ws()
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  peek() {
    return this.s[this.i]
  }

  string() {
    const q = this.s[this.i++]
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === q) return out
      if (q === "'" || c !== '\\') {
        out += c
        continue
      }
      const e = this.s[this.i]
      if (e === undefined) fail('unterminated string')
      this.i++
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail(`invalid escape \\${e}`)
    }
  }

  name() {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.string()
    const st = this.i
    while (this.i < this.s.length && BARE.test(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    this.ws()
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] !== '.') {
        this.i = save
        return parts
      }
      this.i++
      this.ws()
      parts.push(this.name())
    }
  }

  value(prefix) {
    this.ws()
    const c = this.s[this.i]
    if (c === '"' || c === "'") return { type: 'string', value: this.string() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.i < this.s.length && !' \t,]};'.includes(this.s[this.i])) this.i++
    const tok = this.s.slice(st, this.i)
    if (tok === '' || tok[0] === '#' && false) fail('expected a value')
    if (tok === 'true') return { type: 'boolean', value: true }
    if (tok === 'false') return { type: 'boolean', value: false }
    if (INT.test(tok)) return { type: 'integer', value: Number(tok.replace(/_/g, '')) }
    if (FLOAT.test(tok)) return { type: 'float', value: Number(tok.replace(/_/g, '')) }
    fail(`invalid value ${tok}`)
  }

  array(prefix) {
    this.i++
    const items = []
    for (;;) {
      if (this.atEnd()) fail('unterminated array')
      if (this.peek() === ']') {
        this.i++
        return { type: 'array', items, aot: false }
      }
      if (this.peek() === '#') fail('expected a value')
      items.push(this.value(prefix))
      if (this.atEnd()) fail('unterminated array')
      const c = this.peek()
      if (c === ',') this.i++
      else if (c === ']') {
        this.i++
        return { type: 'array', items, aot: false }
      } else fail('unterminated array')
    }
  }

  inline(prefix) {
    this.i++
    const table = newTable()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.peek() === '}') {
      this.i++
      return table
    }
    for (;;) {
      if (this.atEnd()) fail('unterminated inline table')
      const key = this.dotted()
      this.ws()
      if (this.peek() !== '=') fail('expected = in an inline table')
